-- Student ID cards, generated by CampusTwin from student records.
-- One card per student per academic year, each with its own random QR token.
-- Printing again gives the same card; "card lost" revokes it and issues a new
-- token, so the lost card no longer checks as valid. The public check shows
-- only: valid or not, name, class, institution and year (no photo, no contact
-- details). A card also stops checking as valid once the student leaves.
begin;
create table if not exists public.id_card (
  id               bigint generated always as identity primary key,
  school_id        bigint not null default public.current_school_id() references public.school(id) on delete cascade,
  student_id       bigint not null references public.student(id) on delete cascade,
  academic_year_id bigint not null references public.academic_year(id) on delete cascade,
  verify_token     text not null unique default encode(extensions.gen_random_bytes(18), 'hex'),
  status           text not null default 'active' check (status in ('active', 'revoked')),
  prints           int not null default 0 check (prints >= 0),
  issued_at        timestamptz not null default now(),
  revoked_at       timestamptz,
  revoke_reason    text check (revoke_reason is null or char_length(revoke_reason) <= 200)
);
create unique index if not exists uq_id_card_active on public.id_card (student_id, academic_year_id) where status = 'active';

create or replace function public.id_card_guard() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then new.status := 'active'; new.prints := 0; new.revoked_at := null; return new; end if;
  if new.verify_token is distinct from old.verify_token or new.student_id is distinct from old.student_id
     or new.academic_year_id is distinct from old.academic_year_id or new.school_id is distinct from old.school_id then
    raise exception 'An ID card cannot be changed; revoke it and issue a new one';
  end if;
  if old.status = 'revoked' and new.status = 'active' then raise exception 'A revoked ID card cannot be brought back'; end if;
  if new.status = 'revoked' and old.status = 'active' then new.revoked_at := now(); end if;
  if new.prints < old.prints then raise exception 'Prints only go up'; end if;
  return new;
end $$;
drop trigger if exists trg_id_card_guard on public.id_card;
create trigger trg_id_card_guard before insert or update on public.id_card for each row execute function public.id_card_guard();

alter table public.id_card enable row level security;
drop policy if exists tenant_isolation on public.id_card;
create policy tenant_isolation on public.id_card as restrictive for all to authenticated
  using (school_id = public.current_school_id()) with check (school_id = public.current_school_id());
drop policy if exists id_card_read on public.id_card;
create policy id_card_read on public.id_card for select to authenticated using ((select app.is_admin_scope()));
drop policy if exists id_card_office_insert on public.id_card;
create policy id_card_office_insert on public.id_card for insert to authenticated with check ((select app.is_office()));
drop policy if exists id_card_office_update on public.id_card;
create policy id_card_office_update on public.id_card for update to authenticated using ((select app.is_office())) with check ((select app.is_office()));
grant select, insert, update on public.id_card to authenticated;
grant all on public.id_card to service_role;
drop trigger if exists trg_log_change on public.id_card;
create trigger trg_log_change after update on public.id_card for each row execute function public.log_change('ID card');

-- Public check of an ID card from its QR code.
create or replace function public.verify_id_card(p_token text)
returns table (student_name text, class_label text, school_name text, school_place text, year_name text, valid boolean, reason text)
language sql stable security definer set search_path = '' as $$
  select s.full_name,
         (select c.name || '-' || sec.name from public.student_enrollment e join public.section sec on sec.id = e.section_id join public.class c on c.id = sec.class_id
           where e.student_id = s.id and e.academic_year_id = k.academic_year_id limit 1),
         sc.name, sc.place, y.name,
         k.status = 'active' and s.status = 'active' and y.is_current,
         case when k.status = 'revoked' then 'This card has been replaced or reported lost.'
              when s.status <> 'active' then 'The student has left the institution.'
              when not y.is_current then 'This card was for an earlier academic year.'
              else null end
  from public.id_card k
  join public.student s on s.id = k.student_id
  join public.school sc on sc.id = k.school_id
  join public.academic_year y on y.id = k.academic_year_id
  where k.verify_token = p_token and length(p_token) >= 32;
$$;
revoke all on function public.verify_id_card(text) from public;
grant execute on function public.verify_id_card(text) to anon, authenticated;
commit;
